// Día en Bolivia (UTC-4, sin horario de verano). Para probar otro día: GET /webhook/reporte-diario?dia=AAAA-MM-DD
const q = $input.first().json.query ?? {};
let dia = new Date(Date.now() - 4 * 3600e3).toISOString().slice(0, 10);
if (/^\d{4}-\d{2}-\d{2}$/.test(q.dia ?? '')) dia = q.dia;
const siguiente = new Date(Date.parse(`${dia}T00:00:00Z`) + 86400e3).toISOString().slice(0, 10);
return [{ json: { dia, desde: `${dia}T00:00:00-04:00`, hasta: `${siguiente}T00:00:00-04:00` } }];

// Plantilla del correo con los colores de la licorería (blanco y lila)
const e = (v) => String(v ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const plantilla = (titulo, contenido) => `
<div style="font-family:Segoe UI,Arial,sans-serif;background:#f7f4ff;padding:24px;color:#241a38">
  <div style="max-width:620px;margin:0 auto;background:#fff;border:1px solid #ebe7f4;border-radius:14px;overflow:hidden">
    <div style="background:linear-gradient(135deg,#8b5cf6,#6a2fd0);color:#fff;padding:18px 24px;font-size:18px;font-weight:700">Licorería · ${e(titulo)}</div>
    <div style="padding:20px 24px;font-size:14px;line-height:1.5">${contenido}</div>
    <div style="padding:12px 24px;background:#faf9fd;color:#6c6880;font-size:12px">Correo automático de n8n. No responder.</div>
  </div>
</div>`;
const tabla = (cabeceras, filas) => `<table style="border-collapse:collapse;width:100%;font-size:13px"><tr>${cabeceras.map((c, i) =>
  `<th style="text-align:${i ? 'right' : 'left'};padding:6px 8px;border-bottom:2px solid #ddd2fe;color:#6a2fd0">${e(c)}</th>`).join('')}</tr>${filas.map((f) =>
  `<tr>${f.map((v, i) => `<td style="text-align:${i ? 'right' : 'left'};padding:6px 8px;border-bottom:1px solid #ebe7f4">${e(v)}</td>`).join('')}</tr>`).join('')}</table>`;

const { dia } = $('Rango del día').first().json;
const ventas = $('Ventas del día (ms-ventas)').first().json.body ?? [];

const porProducto = {};
let total = 0;
for (const v of ventas) {
  total += Number(v.total);
  for (const i of v.items ?? []) {
    const p = (porProducto[i.productoCodigo] ??= { nombre: i.productoNombre, cantidad: 0, monto: 0 });
    p.cantidad += i.cantidad;
    p.monto += Number(i.subtotal);
  }
}
const filas = Object.entries(porProducto)
  .sort((a, b) => b[1].monto - a[1].monto)
  .map(([codigo, p]) => [`${p.nombre} (${codigo})`, p.cantidad, p.monto.toFixed(2)]);

const agente = $('Agente de reportes (ms-ia)').first().json;
const pdf = $('Descargar PDF').first();
const adjunto = pdf.binary?.reporte;

let contenido = `<p><b>${ventas.length}</b> ventas completadas el ${e(dia)} por un total de <b>Bs ${total.toFixed(2)}</b>.</p>`;
if (!agente.error && agente.resumen) {
  contenido += `<p style="background:#f7f4ff;border-radius:10px;padding:10px 12px">${e(agente.resumen)}</p>`;
}
contenido += filas.length
  ? tabla(['Producto', 'Unidades', 'Monto (Bs)'], filas)
  : '<p style="color:#6c6880">No hubo ventas este día.</p>';
contenido += adjunto
  ? '<p>Se adjunta el reporte en PDF.</p>'
  : '<p style="color:#6c6880;font-size:12px">El PDF no está disponible (ms-ia o ms-gestion no respondió); el detalle sale directo de ms-ventas.</p>';

const salida = { json: { asunto: `Reporte diario de ventas ${dia}: Bs ${total.toFixed(2)}`, cuerpo: plantilla('Reporte diario', contenido), ventas: ventas.length, total } };
if (adjunto) salida.binary = { reporte: adjunto };
return [salida];
